import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.165.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a99876');scene.fog=new THREE.FogExp2('#a99876',.014);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,180);camera.rotation.order='YXZ';
const hemi=new THREE.HemisphereLight('#d9dbbf','#332e24',2.05);scene.add(hemi);
const sun=new THREE.DirectionalLight('#ffdfaa',3.3);sun.position.set(-15,28,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;scene.add(sun);
const fill=new THREE.DirectionalLight('#9bacac',.75);fill.position.set(18,9,-20);scene.add(fill);
const mats={sand:new THREE.MeshStandardMaterial({color:'#827456',roughness:1}),sand2:new THREE.MeshStandardMaterial({color:'#a08c65',roughness:1}),wall:new THREE.MeshStandardMaterial({color:'#776c56',roughness:.95}),dark:new THREE.MeshStandardMaterial({color:'#272d28',roughness:.65}),green:new THREE.MeshStandardMaterial({color:'#46513b',roughness:.82}),metal:new THREE.MeshStandardMaterial({color:'#252a26',metalness:.65,roughness:.4}),lime:new THREE.MeshStandardMaterial({color:'#d8f16a',emissive:'#43520c',emissiveIntensity:.8}),red:new THREE.MeshStandardMaterial({color:'#be4432',emissive:'#67160f',emissiveIntensity:.28})};
const floor=new THREE.Mesh(new THREE.PlaneGeometry(130,130),mats.sand);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
// Dusty quarry perimeter and modular cover
const obstacles=[];
function box(x,y,z,sx,sy,sz,mat,collide=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(collide)obstacles.push({x,z,r:Math.max(sx,sz)*.54});return m}
for(let i=0;i<34;i++){const a=i/34*Math.PI*2,r=35+Math.sin(i*9)*3;const h=4+(i%4)*1.1;box(Math.cos(a)*r,h/2,Math.sin(a)*r,5+Math.random()*5,h,2,mats.wall,false)}
// perimeter fencing, towers and distant silhouettes
for(let side=-1;side<=1;side+=2){box(side*24,1.25,0,.35,2.5,47,mats.dark,false);for(let z=-20;z<=20;z+=4)box(side*24,2.5,z,.55,.09,.09,mats.metal,false);box(side*28,3.8,-19,3,7,3,mats.wall,false);box(side*28,7.5,-19,4,.35,4,mats.dark,false)}
// central quarry cover
box(-7,1,-7,8,2,2,mats.green);box(7,.9,6,7,1.8,2,mats.green);box(-16,.7,9,3,1.4,7,mats.wall);box(15,.7,-10,3,1.4,8,mats.wall);
box(-2,.55,13,5,1.1,2,mats.dark);box(2,.6,-15,6,1.2,2,mats.dark);box(-12,.6,-15,6,1.2,2,mats.green);box(12,.6,15,5,1.2,2,mats.green);
// crates, oil drums and scattered rocks
for(const [x,z] of [[-13,1],[11,-2],[-1,-10],[18,10],[-18,-9],[4,20],[-4,3],[14,-17]]){const c=box(x,.55,z,1.25,1.1,1.25,mats.green);c.rotation.y=Math.random()*.8}
for(const [x,z] of [[-9,15],[9,11],[17,0],[-18,-2],[6,-19]]){const d=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,1.15,12),mats.red);d.position.set(x,.58,z);d.castShadow=true;scene.add(d);obstacles.push({x,z,r:.65});const rim=new THREE.Mesh(new THREE.TorusGeometry(.38,.035,6,12),mats.metal);rim.rotation.x=Math.PI/2;rim.position.set(x,1.15,z);scene.add(rim)}
// sand scrapes and ground detail
for(let i=0;i<46;i++){const p=new THREE.Mesh(new THREE.CircleGeometry(.15+Math.random()*.35,7),new THREE.MeshBasicMaterial({color:i%2?'#b9a67c':'#645940',transparent:true,opacity:.22,depthWrite:false}));p.rotation.x=-Math.PI/2;p.rotation.z=Math.random()*6.2;p.position.set((Math.random()-.5)*53,.012,(Math.random()-.5)*53);scene.add(p)}
// Searchlights and a few warm lamps
for(const [x,z] of [[-22,-18],[22,18]]){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.1,.16,7,7),mats.dark);pole.position.set(x,3.5,z);scene.add(pole);const lamp=new THREE.PointLight('#ffd18c',20,18,2);lamp.position.set(x,6.8,z);scene.add(lamp)}
// Player and first-person weapon
let px=0,pz=0,yaw=0,pitch=0,health=100,armor=50,ammo=30,reserve=180,wave=0,kills=0,elapsed=0,playing=false,paused=false,dead=false,sprinting=false,fireHeld=false,reloading=false,lastShot=0,lastDamage=0,waveWait=0,spawnedWave=0;const keys={};
const weapon=new THREE.Group();const gunMat=new THREE.MeshStandardMaterial({color:'#222824',metalness:.7,roughness:.34});const gunAccent=new THREE.MeshStandardMaterial({color:'#566047',metalness:.4,roughness:.45});
function gunBox(x,y,z,sx,sy,sz,mat){const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);o.position.set(x,y,z);weapon.add(o);return o}
gunBox(0,0,0,.19,.16,.48,gunMat);gunBox(0,-.045,-.32,.08,.08,.35,gunMat);gunBox(0,.1,.015,.1,.055,.22,gunAccent);gunBox(0,-.15,-.02,.105,.2,.11,gunAccent);gunBox(0,-.015,-.39,.045,.045,.27,mats.metal);gunBox(0,.105,-.05,.11,.025,.18,mats.dark);gunBox(.115,.015,.06,.025,.025,.17,mats.lime);weapon.position.set(.32,-.28,-.58);camera.add(weapon);scene.add(camera);
const muzzle=new THREE.PointLight('#ffbd6a',0,4);muzzle.position.set(0,0,-.5);weapon.add(muzzle);
// Enemies assembled from low-poly tactical shapes
const enemies=[],enemyBullets=[];const enemyMat=new THREE.MeshStandardMaterial({color:'#4b493c',roughness:.85}),vestMat=new THREE.MeshStandardMaterial({color:'#333a31',roughness:.9}),skinMat=new THREE.MeshStandardMaterial({color:'#967f61',roughness:.9}),enemyGunMat=new THREE.MeshStandardMaterial({color:'#202522',metalness:.5,roughness:.5});
function makeEnemy(boss=false){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.CapsuleGeometry(boss?.38:.31,boss?.72:.62,4,8),enemyMat);body.position.y=1.1;body.castShadow=true;g.add(body);const vest=new THREE.Mesh(new THREE.BoxGeometry(boss?.64:.52,.62,.34),vestMat);vest.position.set(0,1.22,0);vest.castShadow=true;g.add(vest);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,10,8),skinMat);head.position.y=1.78;head.castShadow=true;g.add(head);const helmet=new THREE.Mesh(new THREE.SphereGeometry(.27,10,7,0,Math.PI*2,0,Math.PI*.56),mats.green);helmet.position.y=1.85;helmet.castShadow=true;g.add(helmet);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.2,.62,.23),enemyMat);leg.position.set(s*.17,.42,0);leg.castShadow=true;g.add(leg);const arm=new THREE.Mesh(new THREE.BoxGeometry(.16,.62,.18),enemyMat);arm.position.set(s*.37,1.19,-.02);arm.rotation.z=s*.13;g.add(arm)}const rifle=new THREE.Mesh(new THREE.BoxGeometry(.1,.11,.82),enemyGunMat);rifle.position.set(.18,1.04,-.48);g.add(rifle);const bar=new THREE.Mesh(new THREE.PlaneGeometry(.9,.08),new THREE.MeshBasicMaterial({color:'#e8614c',transparent:true,depthWrite:false}));bar.position.y=2.28;g.add(bar);const under=new THREE.Mesh(new THREE.PlaneGeometry(.9,.08),new THREE.MeshBasicMaterial({color:'#151914',transparent:true,depthWrite:false}));under.position.y=2.275;g.add(under);g.userData={hp:boss?5:2,boss,attack:1+Math.random()*2,phase:Math.random()*6,bar};scene.add(g);enemies.push(g);return g}
function spawnWave(){wave++;spawnedWave=0;const count=Math.min(3+wave,11);for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,r=20+Math.random()*6;const e=makeEnemy(wave%5===0&&i===0);e.position.set(Math.cos(a)*r,0,Math.sin(a)*r);e.userData.hp= e.userData.boss?5:2;spawnedWave++}document.querySelector('#wave-number').textContent=String(wave).padStart(2,'0');const bars=document.querySelectorAll('.threat-bars i');bars.forEach((b,i)=>b.style.opacity=i<Math.min(5,Math.ceil(wave/2))?'1':'.22');showToast(wave===1?'HOSTILE CONTACT':`WAVE ${String(wave).padStart(2,'0')} INBOUND`);}
function showToast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>el.classList.remove('show'),2100)}
const raycaster=new THREE.Raycaster();raycaster.far=90;let canShoot=true;function shoot(){if(!playing||paused||dead||!canShoot||reloading)return;if(ammo<=0){reload();return}const now=performance.now();if(now-lastShot<115)return;lastShot=now;ammo--;uiAmmo();weapon.position.z=-.49;muzzle.intensity=2.5;document.querySelector('.center-reticle').classList.add('shooting');setTimeout(()=>{weapon.position.z=-.58;muzzle.intensity=0;document.querySelector('.center-reticle').classList.remove('shooting')},65);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const hit=raycaster.intersectObjects(enemies,true).find(h=>h.object.parent?.userData?.hp!==undefined||h.object.parent?.parent?.userData?.hp!==undefined);if(hit){let root=hit.object;while(root&&!root.userData?.hp)root=root.parent;if(root){root.userData.hp--;root.userData.bar.material.color.set(root.userData.hp<=1?'#e85b49':'#e5c66c');root.scale.y=.94;setTimeout(()=>{if(root.parent)root.scale.y=1},60);const ret=document.querySelector('.center-reticle');ret.classList.add('hit');setTimeout(()=>ret.classList.remove('hit'),120);if(root.userData.hp<=0){scene.remove(root);enemies.splice(enemies.indexOf(root),1);kills++;document.querySelector('#ammo-reserve').textContent=reserve}}} }
function reload(){if(reloading||ammo>=30||reserve<=0||!playing||paused)return;reloading=true;document.querySelector('#reload-indicator').classList.add('active');setTimeout(()=>{if(!dead){const n=Math.min(30-ammo,reserve);ammo+=n;reserve-=n;uiAmmo()}reloading=false;document.querySelector('#reload-indicator').classList.remove('active')},1250)}
function uiAmmo(){document.querySelector('#ammo-current').textContent=String(ammo).padStart(2,'0');document.querySelector('#ammo-reserve').textContent=String(reserve)}
function damage(n){if(dead||paused)return;lastDamage=elapsed;if(armor>0){const blocked=Math.min(armor,n*.7);armor-=blocked;n-=blocked}health=Math.max(0,health-n);document.querySelector('#health-value').textContent=Math.ceil(health);document.querySelector('#health-bar').style.width=health+'%';document.querySelector('#armor-value').textContent=Math.ceil(armor);document.querySelector('#damage-flash').style.opacity='.8';setTimeout(()=>document.querySelector('#damage-flash').style.opacity='0',130);if(health<=0)gameOver()}
function gameOver(){dead=true;playing=false;document.querySelector('#final-time').textContent=formatTime(elapsed);document.querySelector('#final-wave').textContent=wave;document.querySelector('#end-screen').classList.remove('hidden');document.exitPointerLock?.()}
function formatTime(n){const sec=Math.floor(n);return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
function lock(){if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.()}
function start(){if(dead){reset()}document.querySelector('#start-screen').classList.add('hidden');document.querySelector('#pause-screen').classList.add('hidden');document.querySelector('#end-screen').classList.add('hidden');playing=true;paused=false;lock();if(wave===0)spawnWave()}
function reset(){for(const e of [...enemies])scene.remove(e);enemies.length=0;px=0;pz=0;yaw=0;pitch=0;health=100;armor=50;ammo=30;reserve=180;wave=0;kills=0;elapsed=0;dead=false;reloading=false;uiAmmo();document.querySelector('#health-value').textContent='100';document.querySelector('#health-bar').style.width='100%';document.querySelector('#armor-value').textContent='50'}
function togglePause(){if(!playing||dead)return;paused=!paused;document.querySelector('#pause-screen').classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.();else lock()}
document.querySelector('#deploy-btn').onclick=start;document.querySelector('#resume-btn').onclick=()=>{paused=false;document.querySelector('#pause-screen').classList.add('hidden');lock()};document.querySelector('#retry-btn').onclick=()=>{reset();start()};document.querySelector('#sound-btn').onclick=e=>{e.currentTarget.classList.toggle('muted');e.currentTarget.textContent=e.currentTarget.classList.contains('muted')?'×':'♪'};
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&playing&&!paused&&!dead&&matchMedia('(pointer:fine)').matches){paused=true;document.querySelector('#pause-screen').classList.remove('hidden')}});
canvas.addEventListener('click',()=>{if(playing&&!paused&&!document.pointerLockElement&&matchMedia('(pointer:fine)').matches)lock();else if(playing&&!paused)shoot()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&playing&&!paused){yaw-=e.movementX*.0022;pitch-=e.movementY*.0022;pitch=Math.max(-1.35,Math.min(1.35,pitch))}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='Escape'&&playing)togglePause()});document.addEventListener('keyup',e=>{keys[e.code]=false});document.addEventListener('mousedown',e=>{if(e.button===0&&playing&&!paused)fireHeld=true});document.addEventListener('mouseup',()=>fireHeld=false);document.addEventListener('contextmenu',e=>e.preventDefault());
// Mobile virtual movement, look and combat controls
let moveTouch={x:0,y:0};const stick=document.querySelector('#move-stick');let stickId=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)updateStick(e)});function updateStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=35,k=Math.min(1,max/(d||1));moveTouch={x:dx*k/max,y:dy*k/max};stick.querySelector('i').style.transform=`translate(calc(-50% + ${moveTouch.x*35}px),calc(-50% + ${moveTouch.y*35}px))`}
function resetStick(e){if(e.pointerId===stickId){stickId=null;moveTouch={x:0,y:0};stick.querySelector('i').style.transform='translate(-50%,-50%)'}}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
let lookId=null,lookX=0,lookY=0;const lookzone=document.querySelector('#look-zone');lookzone.addEventListener('pointerdown',e=>{lookId=e.pointerId;lookX=e.clientX;lookY=e.clientY;lookzone.setPointerCapture(e.pointerId)});lookzone.addEventListener('pointermove',e=>{if(e.pointerId===lookId){yaw-=(e.clientX-lookX)*.006;pitch-=(e.clientY-lookY)*.006;pitch=Math.max(-1.35,Math.min(1.35,pitch));lookX=e.clientX;lookY=e.clientY}});lookzone.addEventListener('pointerup',()=>lookId=null);document.querySelector('#touch-fire').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true});document.querySelector('#touch-fire').addEventListener('pointerup',()=>fireHeld=false);document.querySelector('#touch-fire').addEventListener('pointercancel',()=>fireHeld=false);document.querySelector('#touch-reload').addEventListener('pointerdown',e=>{e.preventDefault();reload()});document.querySelector('#touch-sprint').addEventListener('pointerdown',()=>sprinting=true);document.querySelector('#touch-sprint').addEventListener('pointerup',()=>sprinting=false);document.querySelector('#touch-sprint').addEventListener('pointercancel',()=>sprinting=false);
function playerMove(dt){const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-moveTouch.y;const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveTouch.x;const len=Math.hypot(forward,side)||1, speed=(keys.ShiftLeft||keys.ShiftRight||sprinting?8.2:5.2)*dt;const dx=(Math.sin(yaw)*forward+Math.cos(yaw)*side)/len*speed,dz=(-Math.cos(yaw)*forward+Math.sin(yaw)*side)/len*speed;const nx=px+dx,nz=pz+dz;if(Math.abs(nx)<22&&!obstacles.some(o=>Math.hypot(nx-o.x,nz-o.z)<o.r+.38))px=nx;if(Math.abs(nz)<22&&!obstacles.some(o=>Math.hypot(px-o.x,nz-o.z)<o.r+.38))pz=nz;camera.position.set(px,1.68+Math.sin(elapsed*9)*.025*Math.min(1,Math.hypot(forward,side)),pz);camera.rotation.set(pitch,yaw,0,'YXZ');weapon.rotation.z=(side*.012);}
function updateEnemies(dt){for(const e of [...enemies]){const d=Math.hypot(px-e.position.x,pz-e.position.z);const dx=px-e.position.x,dz=pz-e.position.z;e.rotation.y=Math.atan2(-dx,-dz);e.userData.phase+=dt*7;if(d>5.6){const sp=(e.userData.boss?1.5:2.05)*dt;let nx=e.position.x+dx/d*sp,nz=e.position.z+dz/d*sp;if(!obstacles.some(o=>Math.hypot(nx-o.x,nz-o.z)<o.r+.7)){e.position.x=nx;e.position.z=nz}else{e.position.x+=Math.sign(dz)*sp*.6;e.position.z-=Math.sign(dx)*sp*.6}}else if(d<1.6){e.userData.attack-=dt;if(e.userData.attack<=0){damage(e.userData.boss?13:9);e.userData.attack=1.15+Math.random()*.8}}else{e.userData.attack-=dt;if(e.userData.attack<=0){e.userData.attack=1.7+Math.random()*1.8;if(Math.random()<.78){const start=new THREE.Vector3(e.position.x,1.3,e.position.z),end=new THREE.Vector3(px,1.45,pz);const geo=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:'#ff6a4e',transparent:true,opacity:.75}));scene.add(line);setTimeout(()=>{scene.remove(line);geo.dispose()},90);if(d<17&&Math.random()<.48)damage(e.userData.boss?12:7)}}}e.userData.bar.lookAt(camera.position);e.userData.bar.position.y=2.35+(e.userData.boss?.25:0);e.children[0].position.y=1.1+Math.sin(e.userData.phase)*.025;}
// Simple threat pips on the minimap
const map=document.querySelector('#map-enemies');map.innerHTML='';enemies.slice(0,10).forEach(e=>{const dot=document.createElement('i');dot.className='map-enemy';dot.style.left=`${50+(e.position.x-px)*2.1}%`;dot.style.top=`${50+(e.position.z-pz)*2.1}%`;map.append(dot)})}
function update(dt){if(playing&&!paused&&!dead){elapsed+=dt;document.querySelector('#match-clock').textContent=formatTime(elapsed);playerMove(dt);if(fireHeld)shoot();updateEnemies(dt);if(elapsed-lastDamage>10&&health<100){health=Math.min(100,health+dt*2);document.querySelector('#health-value').textContent=Math.ceil(health);document.querySelector('#health-bar').style.width=health+'%'}if(enemies.length===0){waveWait+=dt;if(waveWait>2.8){waveWait=0;reserve=Math.min(240,reserve+30);uiAmmo();spawnWave()}}else waveWait=0;const bearing=(Math.round((yaw*180/Math.PI+360)%360)+360)%360;document.querySelector('#bearing').textContent=String(bearing).padStart(3,'0')}}
const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.05);update(dt);renderer.render(scene,camera)}frame();
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight)}addEventListener('resize',resize);

