import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.165.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a99876');scene.fog=new THREE.FogExp2('#a99876',.014);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,180);camera.rotation.order='YXZ';
const hemi=new THREE.HemisphereLight('#d9dbbf','#332e24',2.05);scene.add(hemi);
const sun=new THREE.DirectionalLight('#ffdfaa',3.3);sun.position.set(-15,28,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;scene.add(sun);
const fill=new THREE.DirectionalLight('#9bacac',.75);fill.position.set(18,9,-20);scene.add(fill);
const mats={sand:new THREE.MeshStandardMaterial({color:'#827456',roughness:1}),sand2:new THREE.MeshStandardMaterial({color:'#a08c65',roughness:1}),wall:new THREE.MeshStandardMaterial({color:'#776c56',roughness:.95}),dark:new THREE.MeshStandardMaterial({color:'#272d28',roughness:.65}),green:new THREE.MeshStandardMaterial({color:'#46513b',roughness:.82}),metal:new THREE.MeshStandardMaterial({color:'#252a26',metalness:.65,roughness:.4}),lime:new THREE.MeshStandardMaterial({color:'#d8f16a',emissive:'#43520c',emissiveIntensity:.8}),red:new THREE.MeshStandardMaterial({color:'#be4432',emissive:'#67160f',emissiveIntensity:.28})};
const floor=new THREE.Mesh(new THREE.PlaneGeometry(130,130),mats.sand);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
// Dusty quarry perimeter and modular cover
const obstacles=[];
function box(x,y,z,sx,sy,sz,mat,collide=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(collide)obstacles.push({x,z,r:Math.max(sx,sz)*.54});return m}
